export const MARKET_CODES = Object.keys(MARKETS) as MarketCode[];
export const DEFAULT_MARKET: MarketCode = "IN";
export const MARKET_COOKIE = "amazon-market";

const COUNTRY_TO_MARKET: Record<string, MarketCode> = {
  IN: "IN",
  US: "US",
  GB: "GB",
  UK: "GB",
  DE: "DE",
  AE: "AE",
  CA: "CA",
  AU: "AU",
  SG: "SG"
};

const TIMEZONE_TO_MARKET: Record<string, MarketCode> = {
  "Asia/Kolkata": "IN",
  "Asia/Calcutta": "IN",
  "America/New_York": "US",
  "America/Chicago": "US",
  "America/Denver": "US",
  "America/Los_Angeles": "US",
  "America/Toronto": "CA",
  "America/Vancouver": "CA",
  "Europe/London": "GB",
  "Europe/Berlin": "DE",
  "Asia/Dubai": "AE",
  "Australia/Sydney": "AU",
  "Australia/Melbourne": "AU",
  "Asia/Singapore": "SG"
};

export function getMarket(code?: string | null): Market {
  const key = (code?.toUpperCase() as MarketCode) ?? DEFAULT_MARKET;
  return MARKETS[key in MARKETS ? key : DEFAULT_MARKET];
}

export function isValidMarket(code: string): code is MarketCode {
  return code in MARKETS;
}

export function countryToMarket(country?: string | null): MarketCode {
  if (!country) return DEFAULT_MARKET;
  return COUNTRY_TO_MARKET[country.toUpperCase()] ?? DEFAULT_MARKET;
}

export function timezoneToMarket(timezone?: string | null): MarketCode {
  if (!timezone) return DEFAULT_MARKET;
  return TIMEZONE_TO_MARKET[timezone] ?? DEFAULT_MARKET;
}

export function detectMarketFromAcceptLanguage(header?: string | null): MarketCode {
  if (!header) return DEFAULT_MARKET;
  const lower = header.toLowerCase();
  if (lower.includes("en-in") || lower.includes("hi")) return "IN";
  if (lower.includes("en-gb")) return "GB";
  if (lower.includes("de")) return "DE";
  if (lower.includes("en-au")) return "AU";
  if (lower.includes("en-ca") || lower.includes("fr-ca")) return "CA";
  if (lower.includes("en-sg")) return "SG";
  if (lower.includes("en-us")) return "US";
  return DEFAULT_MARKET;
}

import type { Market, MarketCode } from "@/lib/markets";
import { getMarket } from "@/lib/markets";

/** Convert INR base price stored in DB to local market currency */
export function convertFromINR(inrPrice: number, marketCode?: MarketCode | string | null): number {
  const market = getMarket(marketCode);
  const converted = inrPrice * market.exchangeRate;
  return market.currency === "INR" ? Math.round(converted) : Math.round(converted * 100) / 100;
}

export function formatPriceFromINR(inrPrice: number, marketCode?: MarketCode | string | null): string {
  const market = getMarket(marketCode);
  const value = convertFromINR(inrPrice, marketCode);
  const fractionDigits = market.currency === "INR" || market.currency === "JPY" ? 0 : 2;
  return new Intl.NumberFormat(market.locale, {
    style: "currency",
    currency: market.currency,
    maximumFractionDigits: fractionDigits,
    minimumFractionDigits: fractionDigits
  }).format(value);
}

export function formatLocalPrice(value: number, marketCode?: MarketCode | string | null): string {
  const market = getMarket(marketCode);
  const fractionDigits = market.currency === "INR" || market.currency === "JPY" ? 0 : 2;
  return new Intl.NumberFormat(market.locale, {
    style: "currency",
    currency: market.currency,
    maximumFractionDigits: fractionDigits,
    minimumFractionDigits: fractionDigits
  }).format(value);
}

type OrderTotalsInput = {
  subtotalINR: number;
  marketCode?: MarketCode | string | null;
  isPrime?: boolean;
  deliveryMethod?: "standard" | "express";
  couponCode?: string;
};

type OrderTotals = {
  subtotal: number;
  shipping: number;
  tax: number;
  couponDiscount: number;
  total: number;
  market: Market;
};

export function computeOrderTotals({
  subtotalINR,
  marketCode,
  isPrime = true,
  deliveryMethod = "standard",
  couponCode
}: OrderTotalsInput): OrderTotals {
  const market = getMarket(marketCode);
  const subtotal = convertFromINR(subtotalINR, marketCode);
  const coupon = couponCode ? applyCoupon(subtotal, couponCode, market) : { discount: 0 };
  const taxable = Math.max(0, subtotal - coupon.discount);
  const shipping =
    isPrime || taxable >= market.shipping.freeThreshold
      ? deliveryMethod === "express"
        ? market.shipping.expressFee
        : 0
      : market.shipping.flatRate + (deliveryMethod === "express" ? market.shipping.expressFee : 0);
  const tax = Math.round(taxable * market.tax.rate * 100) / 100;
  const total = Math.round((taxable + shipping + tax) * 100) / 100;

  return {
    subtotal,
    shipping,
    tax,
    couponDiscount: coupon.discount,
    total,
    market
  };
}

function applyCoupon(
  subtotal: number,
  code: string,
  market: Market
): { discount: number; message?: string } {
  const coupons: Record<string, { pct?: number; amt?: number; minINR: number }> = {
    SAVE10: { pct: 10, minINR: 999 },
    FLAT500: { amt: 500, minINR: 2999 },
    PRIME20: { pct: 20, minINR: 1499 }
  };

  const coupon = coupons[code.toUpperCase()];
  if (!coupon) return { discount: 0, message: "Invalid coupon code" };

  const minLocal = convertFromINR(coupon.minINR, market.code);
  if (subtotal < minLocal) {
    return {
      discount: 0,
      message: `Minimum order ${formatLocalPrice(minLocal, market.code)} required`
    };
  }

  const discount = coupon.pct
    ? Math.round((subtotal * coupon.pct) / 100 * 100) / 100
    : Math.min(convertFromINR(coupon.amt ?? 0, market.code), subtotal);

  return { discount, message: "Coupon applied successfully" };
}

export { applyCoupon as applyMarketCoupon };

import type { MarketCode } from "@/lib/markets";
import { getMarket } from "@/lib/markets";
import { applyMarketCoupon, computeOrderTotals, convertFromINR, formatLocalPrice } from "@/lib/pricing";

export function isPostalServiceable(postalCode: string, marketCode?: MarketCode | string | null): boolean {
  const market = getMarket(marketCode);
  return market.postal.pattern.test(postalCode.trim());
}

/** @deprecated use isPostalServiceable */
export function isPincodeServiceable(pincode: string): boolean {
  return isPostalServiceable(pincode, "IN");
}

export function estimateDeliveryDate(
  postalCode?: string,
  isPrime = true,
  marketCode?: MarketCode | string | null
): string {
  const market = getMarket(marketCode);
  let days: number;

  if (isPrime) {
    const firstChar = postalCode?.trim().charAt(0);
    if (market.code === "IN") {
      days = firstChar === "1" ? 1 : 2;
    } else if (market.code === "US" || market.code === "CA") {
      days = firstChar && "0123".includes(firstChar) ? 1 : 2;
    } else if (market.code === "GB" || market.code === "DE" || market.code === "AU") {
      days = 2;
    } else {
      days = 2;
    }
  } else {
    days = market.code === "IN" ? 5 : 7;
  }

  const date = new Date();
  date.setDate(date.getDate() + days);
  return date.toLocaleDateString(market.locale, {
    weekday: "long",
    day: "numeric",
    month: "long"
  });
}

export function calculateTax(subtotalINR: number, marketCode?: MarketCode | string | null): number {
  return computeOrderTotals({ subtotalINR, marketCode }).tax;
}

export function calculateShipping(
  subtotalINR: number,
  isPrime: boolean,
  marketCode?: MarketCode | string | null
): number {
  return computeOrderTotals({ subtotalINR, marketCode, isPrime }).shipping;
}

export function applyCoupon(
  subtotalINR: number,
  code: string,
  marketCode?: MarketCode | string | null
): { discount: number; message: string } {
  const market = getMarket(marketCode);
  const subtotal = convertFromINR(subtotalINR, marketCode);
  const result = applyMarketCoupon(subtotal, code, market);
  return {
    discount: result.discount,
    message: result.message ?? (result.discount > 0 ? "Coupon applied successfully" : "Invalid coupon code")
  };
}

export function formatCouponMinimum(minINR: number, marketCode?: MarketCode | string | null): string {
  return formatLocalPrice(convertFromINR(minINR, marketCode), marketCode);
}

