"use client";

import { create } from "zustand";
import { persist } from "zustand/middleware";

import type { MarketCode } from "@/lib/markets";
import { DEFAULT_MARKET, getMarket } from "@/lib/markets";
import { useDeliveryStore } from "@/components/providers/delivery-store";

type LocaleState = {
  market: MarketCode;
  detectedMarket: MarketCode | null;
  initialized: boolean;
  setMarket: (market: MarketCode) => void;
  initializeFromDetection: (detected: MarketCode) => void;
};

export const useLocaleStore = create<LocaleState>()(
  persist(
    (set, get) => ({
      market: DEFAULT_MARKET,
      detectedMarket: null,
      initialized: false,
      setMarket: (market) => {
        const config = getMarket(market);
        useDeliveryStore.getState().setLocation(config.defaultLocation.postalCode, config.defaultLocation.city, market);
        set({ market, initialized: true });
        document.cookie = `amazon-market=${market};path=/;max-age=31536000;SameSite=Lax`;
      },
      initializeFromDetection: (detected) => {
        if (get().initialized) return;
        const config = getMarket(detected);
        useDeliveryStore.getState().setLocation(config.defaultLocation.postalCode, config.defaultLocation.city, detected);
        set({ market: detected, detectedMarket: detected, initialized: true });
        document.cookie = `amazon-market=${detected};path=/;max-age=31536000;SameSite=Lax`;
      }
    }),
    {
      name: "amazon-global-market",
      partialize: (state) => ({ market: state.market, initialized: state.initialized })
    }
  )
);

"use client";

import { create } from "zustand";
import { persist } from "zustand/middleware";

import type { MarketCode } from "@/lib/markets";
import { DEFAULT_MARKET, getMarket } from "@/lib/markets";

type DeliveryState = {
  pincode: string;
  city: string;
  market: MarketCode;
  setLocation: (pincode: string, city: string, market?: MarketCode) => void;
};

const defaultMarket = getMarket(DEFAULT_MARKET);

export const useDeliveryStore = create<DeliveryState>()(
  persist(
    (set) => ({
      pincode: defaultMarket.defaultLocation.postalCode,
      city: defaultMarket.defaultLocation.city,
      market: DEFAULT_MARKET,
      setLocation: (pincode, city, market) =>
        set((state) => ({
          pincode,
          city,
          market: market ?? state.market
        }))
    }),
    { name: "amazon-global-delivery" }
  )
);

"use client";

import { useEffect } from "react";

import { useLocaleStore } from "@/components/providers/locale-store";
import type { MarketCode } from "@/lib/markets";
import { isValidMarket, timezoneToMarket } from "@/lib/markets";

export function MarketInit() {
  const initialized = useLocaleStore((s) => s.initialized);
  const initializeFromDetection = useLocaleStore((s) => s.initializeFromDetection);

  useEffect(() => {
    if (initialized) return;

    const cookieMarket = document.cookie
      .split("; ")
      .find((row) => row.startsWith("amazon-market="))
      ?.split("=")[1];

    if (cookieMarket && isValidMarket(cookieMarket)) {
      initializeFromDetection(cookieMarket);
      return;
    }

    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const fallback = timezoneToMarket(timezone);

    fetch("/api/geo/detect", { headers: { "x-timezone": timezone } })
      .then((res) => res.json())
      .then((data: { market?: MarketCode }) => {
        const detected = data.market && isValidMarket(data.market) ? data.market : fallback;
        initializeFromDetection(detected);
      })
      .catch(() => initializeFromDetection(fallback));
  }, [initialized, initializeFromDetection]);

  return null;
}

import { NextResponse } from "next/server";

import {
  countryToMarket,
  detectMarketFromAcceptLanguage,
  isValidMarket,
  timezoneToMarket,
  type MarketCode
} from "@/lib/markets";

export async function GET(request: Request) {
  const country =
    request.headers.get("x-vercel-ip-country") ??
    request.headers.get("cf-ipcountry") ??
    request.headers.get("x-country-code");

  const timezone = request.headers.get("x-timezone");
  const acceptLanguage = request.headers.get("accept-language");

  let market: MarketCode = countryToMarket(country);

  if (!country && timezone) {
    market = timezoneToMarket(timezone);
  }

  if (!country && !timezone) {
    market = detectMarketFromAcceptLanguage(acceptLanguage);
  }

  if (!isValidMarket(market)) {
    market = "IN";
  }

  return NextResponse.json({ market, country: country ?? null });
}

"use client";

import { useLocaleStore } from "@/components/providers/locale-store";
import { getMarket } from "@/lib/markets";
import { convertFromINR, formatPriceFromINR } from "@/lib/pricing";

export function useMarket() {
  const market = useLocaleStore((s) => s.market);
  const setMarket = useLocaleStore((s) => s.setMarket);
  const config = getMarket(market);

  return {
    market,
    config,
    setMarket,
    formatPrice: (inrPrice: number) => formatPriceFromINR(inrPrice, market),
    convertPrice: (inrPrice: number) => convertFromINR(inrPrice, market)
  };
}

