import { getServerSession } from "next-auth";
import { NextResponse } from "next/server";
import { z } from "zod";

import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

const couponSchema = z.object({
  code: z.string().min(3),
  description: z.string().min(3),
  discountPct: z.number().int().min(1).max(90).optional(),
  discountAmt: z.number().positive().optional(),
  minOrder: z.number().min(0).default(0),
  maxUses: z.number().int().positive().optional(),
  expiresAt: z.string().datetime().optional()
});

export async function GET() {
  const session = await getServerSession(authOptions);
  if (session?.user?.role !== "ADMIN") {
    return NextResponse.json({ message: "Admin access required" }, { status: 403 });
  }

  const coupons = await prisma.coupon.findMany({ orderBy: { createdAt: "desc" } });
  return NextResponse.json({ coupons });
}

export async function POST(request: Request) {
  const session = await getServerSession(authOptions);
  if (session?.user?.role !== "ADMIN") {
    return NextResponse.json({ message: "Admin access required" }, { status: 403 });
  }

  const payload = couponSchema.parse(await request.json());
  const coupon = await prisma.coupon.create({
    data: {
      code: payload.code.toUpperCase(),
      description: payload.description,
      discountPct: payload.discountPct,
      discountAmt: payload.discountAmt,
      minOrder: payload.minOrder,
      maxUses: payload.maxUses,
      expiresAt: payload.expiresAt ? new Date(payload.expiresAt) : undefined
    }
  });

  return NextResponse.json({ coupon }, { status: 201 });
}

import { getServerSession } from "next-auth";
import { NextResponse } from "next/server";

import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { changePasswordSchema, profileSchema } from "@/lib/validators";
import bcrypt from "bcryptjs";

export async function GET() {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id) {
    return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  }

  const user = await prisma.user.findUnique({
    where: { id: session.user.id },
    select: { id: true, name: true, email: true, phone: true, isPrime: true, emailVerified: true, createdAt: true }
  });

  return NextResponse.json({ user });
}

export async function PATCH(request: Request) {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id) {
    return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  }

  const body = await request.json();

  if (body.currentPassword && body.newPassword) {
    const parsed = changePasswordSchema.parse(body);
    const user = await prisma.user.findUnique({ where: { id: session.user.id } });
    if (!user?.password) {
      return NextResponse.json({ message: "Password login not available for this account" }, { status: 400 });
    }
    const valid = await bcrypt.compare(parsed.currentPassword, user.password);
    if (!valid) {
      return NextResponse.json({ message: "Current password is incorrect" }, { status: 400 });
    }
    await prisma.user.update({
      where: { id: session.user.id },
      data: { password: await bcrypt.hash(parsed.newPassword, 12) }
    });
    return NextResponse.json({ message: "Password updated" });
  }

  const parsed = profileSchema.parse(body);
  const user = await prisma.user.update({
    where: { id: session.user.id },
    data: {
      name: parsed.name,
      phone: parsed.phone
    },
    select: { id: true, name: true, email: true, phone: true }
  });

  return NextResponse.json({ user });
}

import { randomBytes } from "crypto";
import { NextResponse } from "next/server";

import { prisma } from "@/lib/prisma";
import { passwordResetRequestSchema } from "@/lib/validators";

export async function POST(request: Request) {
  const { email } = passwordResetRequestSchema.parse(await request.json());
  const user = await prisma.user.findUnique({ where: { email } });

  if (!user) {
    return NextResponse.json({ message: "If that email exists, a reset link has been sent." });
  }

  const token = randomBytes(32).toString("hex");
  const expires = new Date(Date.now() + 60 * 60 * 1000);

  await prisma.verificationToken.deleteMany({ where: { identifier: email } });
  await prisma.verificationToken.create({
    data: { identifier: email, token, expires }
  });

  const resetUrl = `${process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000"}/reset-password?token=${token}&email=${encodeURIComponent(email)}`;

  if (process.env.NODE_ENV !== "production") {
    console.log("[password-reset]", resetUrl);
  }

  return NextResponse.json({
    message: "If that email exists, a reset link has been sent.",
    ...(process.env.NODE_ENV !== "production" ? { resetUrl } : {})
  });
}

import bcrypt from "bcryptjs";
import { NextResponse } from "next/server";

import { prisma } from "@/lib/prisma";
import { passwordResetSchema } from "@/lib/validators";

export async function POST(request: Request) {
  const { token, email, password } = passwordResetSchema.parse(await request.json());

  const record = await prisma.verificationToken.findFirst({
    where: { identifier: email, token }
  });

  if (!record || record.expires < new Date()) {
    return NextResponse.json({ message: "Invalid or expired reset link" }, { status: 400 });
  }

  await prisma.user.update({
    where: { email },
    data: { password: await bcrypt.hash(password, 12) }
  });

  await prisma.verificationToken.deleteMany({ where: { identifier: email } });

  return NextResponse.json({ message: "Password reset successful" });
}

import { randomBytes } from "crypto";
import { getServerSession } from "next-auth";
import { NextResponse } from "next/server";

import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export async function POST(request: Request) {
  const session = await getServerSession(authOptions);
  const body = (await request.json()) as { token?: string; email?: string };

  if (body.token && body.email) {
    const record = await prisma.verificationToken.findFirst({
      where: { identifier: body.email, token: body.token }
    });
    if (!record || record.expires < new Date()) {
      return NextResponse.json({ message: "Invalid or expired verification link" }, { status: 400 });
    }
    await prisma.user.update({
      where: { email: body.email },
      data: { emailVerified: new Date() }
    });
    await prisma.verificationToken.deleteMany({ where: { identifier: body.email } });
    return NextResponse.json({ message: "Email verified" });
  }

  if (!session?.user?.email) {
    return NextResponse.json({ message: "Unauthorized" }, { status: 401 });
  }

  const token = randomBytes(32).toString("hex");
  const expires = new Date(Date.now() + 24 * 60 * 60 * 1000);
  await prisma.verificationToken.deleteMany({ where: { identifier: session.user.email } });
  await prisma.verificationToken.create({
    data: { identifier: session.user.email, token, expires }
  });

  const verifyUrl = `${process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000"}/verify-email?token=${token}&email=${encodeURIComponent(session.user.email)}`;
  if (process.env.NODE_ENV !== "production") {
    console.log("[email-verify]", verifyUrl);
  }

  return NextResponse.json({
    message: "Verification email sent",
    ...(process.env.NODE_ENV !== "production" ? { verifyUrl } : {})
  });
}

import { getServerSession } from "next-auth";
import { NextResponse } from "next/server";

import { authOptions } from "@/lib/auth";
import { absoluteUrl } from "@/lib/utils";
import { stripe } from "@/lib/stripe";

const PRIME_PRICE_ID = process.env.STRIPE_PRIME_PRICE_ID;

export async function POST() {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id || !session.user.email) {
    return NextResponse.json({ message: "Sign in required" }, { status: 401 });
  }

  if (!PRIME_PRICE_ID) {
    return NextResponse.json(
      { message: "Prime subscription is not configured. Set STRIPE_PRIME_PRICE_ID in .env" },
      { status: 503 }
    );
  }

  const checkout = await stripe.checkout.sessions.create({
    mode: "subscription",
    payment_method_types: ["card"],
    customer_email: session.user.email,
    line_items: [{ price: PRIME_PRICE_ID, quantity: 1 }],
    success_url: absoluteUrl("/dashboard/prime?subscribed=1"),
    cancel_url: absoluteUrl("/prime"),
    metadata: { userId: session.user.id },
    subscription_data: {
      metadata: { userId: session.user.id }
    }
  });

  return NextResponse.json({ url: checkout.url });
}

