    const res = await fetch("/api/auth/verify-email", { method: "POST" });
    const data = await res.json();
    if (res.ok) {
      toast.success(data.message, { description: data.verifyUrl });
    } else {
      toast.error(data.message ?? "Failed to send verification");
    }
  }

  return (
    <DashboardShell title="Login & Security">
      <div className="space-y-4">
        <div className="amazon-card">
          <h2 className="font-bold">Change password</h2>
          <SecurityForm />
        </div>
        <div className="amazon-card">
          <h2 className="font-bold">Email verification</h2>
          <p className="mt-2 text-sm text-slate-600">Verify your email address for account security.</p>
          <Button variant="outline" className="mt-4" onClick={sendVerification}>
            Send verification email
          </Button>
        </div>
      </div>
    </DashboardShell>
  );
}

"use client";

import Link from "next/link";
import { useEffect, useState } from "react";

import { DashboardShell } from "@/components/dashboard/dashboard-shell";
import type { NotificationItem } from "@/types";

export default function NotificationsPage() {
  const [notifications, setNotifications] = useState<NotificationItem[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("/api/notifications")
      .then((res) => res.json())
      .then((data: { notifications: NotificationItem[] }) => {
        setNotifications(
          data.notifications.map((n) => ({
            ...n,
            createdAt: n.createdAt
          }))
        );
      })
      .finally(() => setLoading(false));
  }, []);

  async function markRead(id: string) {
    await fetch("/api/notifications", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ id })
    });
    setNotifications((list) => list.map((item) => (item.id === id ? { ...item, read: true } : item)));
  }

  async function markAllRead() {
    await fetch("/api/notifications", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ markAllRead: true })
    });
    setNotifications((list) => list.map((item) => ({ ...item, read: true })));
  }

  return (
    <DashboardShell title="Notifications">
      <div className="mb-4 flex justify-end">
        <button type="button" onClick={markAllRead} className="text-sm font-bold text-amazon-teal hover:underline">
          Mark all as read
        </button>
      </div>
      <div className="space-y-3">
        {loading && <p className="text-sm text-slate-500">Loading notifications...</p>}
        {!loading && notifications.length === 0 && (
          <p className="text-sm text-slate-500">No notifications yet.</p>
        )}
        {notifications.map((n) => (
          <article
            key={n.id}
            className={`amazon-card ${!n.read ? "border-l-4 border-l-amazon-orange" : ""}`}
          >
            <div className="flex items-start justify-between gap-4">
              <div>
                <p className="text-xs font-bold uppercase text-slate-500">{n.type}</p>
                <h3 className="font-bold">{n.title}</h3>
                <p className="mt-1 text-sm text-slate-600 dark:text-slate-300">{n.body}</p>
                {n.link && (
                  <Link href={n.link} className="mt-2 inline-block text-sm text-amazon-teal hover:underline">
                    View details
                  </Link>
                )}
              </div>
              {!n.read && (
                <button type="button" className="text-xs text-amazon-teal hover:underline" onClick={() => markRead(n.id)}>
                  Mark read
                </button>
              )}
            </div>
          </article>
        ))}
      </div>
    </DashboardShell>
  );
}

"use client";

import Link from "next/link";
import { FormEvent, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";

export default function ForgotPasswordPage() {
  const [sent, setSent] = useState(false);
  const [loading, setLoading] = useState(false);

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const email = String(form.get("email") ?? "");
    setLoading(true);
    try {
      const res = await fetch("/api/auth/forgot-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email })
      });
      const data = await res.json();
      setSent(true);
      toast.success(data.message, { description: data.resetUrl });
    } catch {
      toast.error("Failed to send reset link");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="mx-auto max-w-md px-4 py-16">
      <div className="amazon-card">
        <h1 className="text-2xl font-bold">Forgot your password?</h1>
        <p className="mt-2 text-sm text-slate-600">Enter your email and we&apos;ll send a reset link.</p>
        {sent ? (
          <p className="mt-4 text-sm text-amazon-green">
            If an account exists, you will receive an email shortly.{" "}
            <Link href="/login" className="text-amazon-teal underline">
              Back to sign in
            </Link>
          </p>
        ) : (
          <form onSubmit={onSubmit} className="mt-6 space-y-4">
            <input
              type="email"
              name="email"
              required
              placeholder="Email"
              className="h-11 w-full rounded border border-slate-200 px-3 dark:border-white/10 dark:bg-slate-950"
            />
            <Button type="submit" className="w-full" disabled={loading}>
              {loading ? "Sending..." : "Send reset link"}
            </Button>
          </form>
        )}
      </div>
    </div>
  );
}

